SELECT ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='feedback_archives' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_unicode_ci')=1 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='feedback_archives')=4 AND (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='feedback_archives' AND CONSTRAINT_NAME IN ('PRIMARY','fk_archive_feedback','fk_archive_actor'))=3) AS satisfied
